import { Redirection } from '@toss/redirect';
import { memo, useEffect, useRef } from 'react';
import { useStore } from '~/app/store/store';

/**
 * 리디렉션을 감지하고 발생시키는 컴포넌트
 * - 렌더링 시점 감지: redirectPath가 존재하면 즉시 리디렉션
 * - 이벤트 기반 감지: 포커스/가시성 변경 시 redirectPath 확인 후 리디렉션
 */
export const RedirectionTrigger = memo(() => {
  const redirectPath = useStore((state) => state.appConfigSlice.getFormattedRedirectPath());
  const isProcessing = useRef(false);
  const triggerRef = useRef<string | null>(null);

  // 각 함수를 개별적으로 가져와 불필요한 리렌더링 방지
  const getFormattedRedirectPath = useStore((state) => state.appConfigSlice.getFormattedRedirectPath);
  const setRedirectPath = useStore((state) => state.appConfigSlice.setRedirectPath);

  // 포커스와 가시성 변경 이벤트 리스너 등록
  useEffect(() => {
    const handleVisibilityOrFocus = () => {
      if (isProcessing.current) {
        return;
      }

      // 현재 상태의 redirectPath 확인
      const currentRedirectPath = getFormattedRedirectPath();

      if (currentRedirectPath) {
        isProcessing.current = true;

        // 이벤트에 의한 리디렉션은 다음 렌더링 사이클에서 발생시킴
        // 직접 throw하면 React 컴포넌트 외부에서 예외가 발생하여 처리되지 않음
        triggerRef.current = currentRedirectPath;

        // 강제 리렌더링을 위해 상태 업데이트
        // 바로 발생시키면 이벤트 핸들러 내에서 예외가 발생해 React가 처리하지 못함
        setTimeout(() => {
          setRedirectPath(currentRedirectPath);

          // 플래그 초기화
          setTimeout(() => {
            isProcessing.current = false;
          }, 100);
        }, 0);
      }
    };
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        handleVisibilityOrFocus();
      }
    };

    // 이벤트 리스너 등록
    window.addEventListener('focus', handleVisibilityOrFocus);
    window.addEventListener('visibilitychange', handleVisibilityChange);

    // 초기 체크
    handleVisibilityOrFocus();

    // 정리 함수
    return () => {
      window.removeEventListener('focus', handleVisibilityOrFocus);
      window.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [getFormattedRedirectPath, setRedirectPath]);

  // redirectPath가 있으면 리디렉션 발생
  if (redirectPath) {
    throw Redirection.of({ destination: redirectPath });
  }

  return null;
});

RedirectionTrigger.displayName = 'RedirectionTrigger';
