import { RedirectionBoundary } from '@toss/redirect';
import { ReactNode, memo, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useStore } from '~/app/store/store';
import { RedirectionTrigger } from './redirection-trigger';

/**
 * 웹뷰에서 부모창으로 리디렉션을 처리하는 바운더리 컴포넌트
 */
export const WebViewRedirectionBoundary = memo(({ children }: { children: ReactNode }) => {
  const { key } = useLocation();
  const navigate = useNavigate();

  // 현재 창이 자식 창인지 확인
  const isChildWindow = useRef(new URLSearchParams(window.location.search).has('isChildWindow')).current;

  return (
    <RedirectionBoundary
      onRedirect={(redirection) => {
        // 메인 창에서만 상태 초기화 (다음 틱으로 지연)
        setTimeout(() => {
          if (!isChildWindow) {
            const safeResetRedirectPath = useStore.getState().appConfigSlice.safeResetRedirectPath;
            safeResetRedirectPath();
          }

          navigate(redirection.options.destination);
        }, 0);
      }}
      key={key}
    >
      <RedirectionTrigger />
      {children}
    </RedirectionBoundary>
  );
});

WebViewRedirectionBoundary.displayName = 'WebViewRedirectionBoundary';
